package com.lowdetailraids;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class AutomaticLowDetailPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(AutomaticLowDetailPlugin.class);
		RuneLite.main(args);
	}
}

package com.lowdetailraids;

import com.google.inject.Provides;
import java.util.Arrays;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.PluginChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.lowmemory.LowMemoryConfig;
import net.runelite.client.plugins.lowmemory.LowMemoryPlugin;
import org.apache.commons.lang3.tuple.Pair;

@Slf4j
@PluginDescriptor(
	name = "Automatic Low Detail",
	description = "Automatically turn off ground decorations while inside certain areas (like raids)",
	tags = {"memory", "ground", "decorations", "cox", "xeric", "tob", "theatre", "toa", "amascut", "sepulchre", "inferno", "doom", "gauntlet", "cg", "nightmare", "phosani"},
	configName = AutomaticLowDetailPlugin.CONFIG_NAME,
	conflicts = "Low Detail Chambers"
)
public class AutomaticLowDetailPlugin extends Plugin
{
	public static final String CONFIG_NAME = "LowDetailRaidsPlugin";

	private static final int VARP_IN_RAID_ENCOUNTER = 2926;

	private static final Set<Integer> DOOM_REGION_IDS = Set.of(5269, 13668, 14180);
	private static final Set<Integer> NIGHTMARE_REGION_IDS = Set.of(15515);

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ConfigManager configManager;

	@Inject
	private AutomaticLowDetailConfig config;

	private boolean lowDetailModeEnabled = false;
	private boolean hideLowerPlanesEnabled = false;

	private Set<Integer> regionIdsLowDetail = Set.of();
	private Set<Integer> regionIdsHideLowerPlanes = Set.of();

	@Override
	protected void startUp()
	{
		lowDetailModeEnabled = vanillaLowDetailPluginEnabled();
		parseRegionIdsFromConfig();
		clientThread.invoke(this::updateLowDetailMode);
	}

	@Override
	protected void shutDown()
	{
		if (!vanillaLowDetailPluginEnabled() && lowDetailModeEnabled)
		{
			clientThread.invoke(() -> client.changeMemoryMode(false));
			lowDetailModeEnabled = false;
		}

		hideLowerPlanesEnabled = false;

		regionIdsLowDetail.clear();
		regionIdsHideLowerPlanes.clear();
	}

	@Provides
	AutomaticLowDetailConfig getConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AutomaticLowDetailConfig.class);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event.getGroup().equals(AutomaticLowDetailConfig.GROUP))
		{
			parseRegionIdsFromConfig();
			clientThread.invoke(this::updateLowDetailMode);
		}
		else if (event.getGroup().equals(LowMemoryConfig.GROUP))
		{
			lowDetailModeEnabled = vanillaLowDetailPluginEnabled();

			// Can't call updateLowDetailMode() immediately, because the Low Detail plugin is about to call
			// client.changeMemoryMode(), which will undo anything we do now.
			//
			// clientThread.invoke() and clientThread.invokeLater() do not work; we must wait until the end
			// of the client tick.
			clientThread.invokeAtTickEnd(this::updateLowDetailMode);
		}
	}

	@Subscribe
	public void onPluginChanged(PluginChanged event)
	{
		if (event.getPlugin() instanceof LowMemoryPlugin)
		{
			lowDetailModeEnabled = vanillaLowDetailPluginEnabled();
			clientThread.invoke(this::updateLowDetailMode);
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
	{
		if (vanillaLowDetailPluginEnabled())
		{
			return;
		}

		if (gameStateChanged.getGameState() == GameState.STARTING)
		{
			client.changeMemoryMode(false);
			lowDetailModeEnabled = false;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		updateLowDetailMode();
	}

	// Deliberately lower callback priority so that the vanilla Low Detail plugin renders first.
	@Subscribe(priority = -10)
	public void onBeforeRender(BeforeRender beforeRender)
	{
		var wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return;
		}

		if (hideLowerPlanesEnabled)
		{
			wv.getScene().setMinLevel(wv.getPlane());
		}
		else
		{
			// Fallback to whatever the vanilla Low Detail plugin's configuration currently says.
			wv.getScene().setMinLevel(vanillaLowDetailPluginHideLowerPlanesEnabled() ? wv.getPlane() : 0);
		}
	}

	private static Optional<Integer> parseRegionId(String region)
	{
		try
		{
			return Optional.of(Integer.parseInt(region));
		}
		catch (NumberFormatException e)
		{
			return Optional.empty();
		}
	}

	private void parseRegionIdsFromConfig()
	{
		String[] regionIdsLowDetailStrings = config.regionIdsLowDetail().trim().split("\\s*,\\s*");
		regionIdsLowDetail = Arrays.stream(regionIdsLowDetailStrings).map(AutomaticLowDetailPlugin::parseRegionId).filter(Optional::isPresent).map(Optional::get).collect(Collectors.toSet());
		String[] regionIdsHideLowerPlanesStrings = config.regionIdsHideLowerPlanes().trim().split("\\s*,\\s*");
		regionIdsHideLowerPlanes = Arrays.stream(regionIdsHideLowerPlanesStrings).map(AutomaticLowDetailPlugin::parseRegionId).filter(Optional::isPresent).map(Optional::get).collect(Collectors.toSet());
	}

	/**
	 * Attempts to correct the client memory mode depending on whether the player is in a valid region for automatic
	 * low detail mode and if the memory mode really has changed and needs to be adjusted.
	 * <p>
	 * If Runelite's vanilla Low Detail plugin is active, this function will do nothing.
	 * <p>
	 * <strong>This function must be called on the client thread.</strong>
	 */
	private void updateLowDetailMode()
	{
		Pair<Optional<AutomaticLowDetailRegion>, Boolean> regionAndHideLowerPlanes = canEnableLowDetailMode();
		hideLowerPlanesEnabled = regionAndHideLowerPlanes.getRight();

		if (vanillaLowDetailPluginEnabled())
		{
			return;
		}

		Optional<AutomaticLowDetailRegion> region = regionAndHideLowerPlanes.getLeft();
		if (!lowDetailModeEnabled && region.isPresent())
		{
			client.changeMemoryMode(true);
			lowDetailModeEnabled = true;
			log.debug("Automatically enabled Low Detail Mode for region: {}, hideLowerPlanes: {}", region.get(), regionAndHideLowerPlanes.getRight());
		}
		else if (lowDetailModeEnabled && !region.isPresent())
		{
			client.changeMemoryMode(false);
			lowDetailModeEnabled = false;
			log.debug("Automatically disabled Low Detail Mode");
		}
	}

	private Pair<Optional<AutomaticLowDetailRegion>, Boolean> canEnableLowDetailMode()
	{
		// When the client starts it initializes the texture size based on the memory mode setting.
		// Don't set low memory before the login screen is ready to prevent loading the low detail textures,
		// which breaks the gpu plugin due to it requiring the 128x128px textures
		if (client.getGameState().getState() < GameState.LOGIN_SCREEN.getState())
		{
			return Pair.of(Optional.empty(), false);
		}

		if (insideChambersOfXeric())
		{
			return Pair.of(config.chambersOfXericLowDetail() ? Optional.of(AutomaticLowDetailRegion.CHAMBERS_OF_XERIC) : Optional.empty(), config.chambersOfXericHideLowerPlanes());
		}
		else if (insideTheatreOfBlood())
		{
			return Pair.of( config.theatreOfBloodLowDetail() ? Optional.of(AutomaticLowDetailRegion.THEATRE_OF_BLOOD) : Optional.empty(), config.theatreOfBloodHideLowerPlanes());
		}
		else if (insideTombsOfAmascut())
		{
			return Pair.of(config.tombsOfAmascutLowDetail() ? Optional.of(AutomaticLowDetailRegion.TOMBS_OF_AMASCUT) : Optional.empty(), config.tombsOfAmascutHideLowerPlanes());
		}
		else if (insideInferno())
		{
			return Pair.of(config.infernoLowDetail() ? Optional.of(AutomaticLowDetailRegion.INFERNO) : Optional.empty(), config.infernoHideLowerPlanes());
		}
		else if (insideHallowedSepulchre())
		{
			return Pair.of(config.hallowedSepulchreLowDetail() ? Optional.of(AutomaticLowDetailRegion.HALLOWED_SEPULCHRE) : Optional.empty(), config.hallowedSepulchreHideLowerPlanes());
		}
		else if (insideDoomOfMokhaiotl())
		{
			return Pair.of(config.doomOfMokhaiotlLowDetail() ? Optional.of(AutomaticLowDetailRegion.DOOM_OF_MOKHAIOTL) : Optional.empty(), config.doomOfMokhaiotlHideLowerPlanes());
		}
		else if (insideGauntlet())
		{
			return Pair.of(config.gauntletLowDetail() ? Optional.of(AutomaticLowDetailRegion.GAUNTLET) : Optional.empty(), config.gauntletHideLowerPlanes());
		}
		else if (insideNightmare())
		{
			return Pair.of(config.nightmareLowDetail() ? Optional.of(AutomaticLowDetailRegion.NIGHTMARE) : Optional.empty(), config.nightmareHideLowerPlanes());
		}

		return Pair.of(insideRegion(regionIdsLowDetail) ? Optional.of(AutomaticLowDetailRegion.CUSTOM_REGION_ID) : Optional.empty(), insideRegion(regionIdsHideLowerPlanes));
	}

	private boolean insideRaidEncounter()
	{
		return client.getVarpValue(VARP_IN_RAID_ENCOUNTER) != 0;
	}

	// ====================================================================================

	private boolean insideChambersOfXeric()
	{
		if (client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) != 1)
		{
			// Not inside the lobby or the raid levels.
			return false;
		}

		int raidPartyID = client.getVarpValue(VarPlayerID.RAIDS_PARTY_GROUPHOLDER);
		if (raidPartyID == -1)
		{
			// Raid party ID is -1 when:
			// 1. We're not in a raid party at all (e.g. outside the raid)
			// 2. We were in a party but we're currently reloading the raid from the inside stairs
			// 3. We were in a party but then we started the raid
			//
			// Only #3 is a valid reason to enable low detail mode. The other two cases should NOT result
			// in toggling low detail.

			// The plugin crashes if we check RAID_STATE while not inside Chambers, so only check
			// RAID_STATE here now that we know it's safe.
			int raidState = client.getVarbitValue(VarbitID.RAIDS_CLIENT_PROGRESS);
			return raidState != 0 && raidState != 5;
		}

		// We're in the lobby, we haven't started the raid, and we're not currently reloading the raid.
		return true;
	}

	private boolean insideTheatreOfBlood()
	{
		return client.getVarbitValue(VarbitID.TOB_CLIENT_PARTYSTATUS) > 1;
	}

	private boolean insideTombsOfAmascut()
	{
		// TOA doesn't seem to have a convenient Varbit we can check like we can for COX and TOB.
		return insideRaidEncounter() && client.getVarbitValue(VarbitID.TOA_CLIENT_PARTYSTATUS) != 0;
	}

	private boolean insideInferno()
	{
		return client.getVarbitValue(VarbitID.PLAYER_IN_INFERNO) == 1;
	}

	private boolean insideHallowedSepulchre()
	{
		return client.getVarbitValue(VarbitID.HALLOWED_TIME_SPENT) > 0;
	}

	private boolean insideRegion(Set<Integer> regions)
	{
		if (regions.isEmpty())
		{
			return false;
		}

		final var wv = client.getTopLevelWorldView();
		if (wv == null)
		{
			return false;
		}

		final var mapRegions = wv.getMapRegions();
		return mapRegions != null && Arrays.stream(mapRegions).anyMatch(regions::contains);
	}

	private boolean insideInstanceRegion(Set<Integer> regions)
	{
		if (regions.isEmpty())
		{
			return false;
		}

		final var wv = client.getTopLevelWorldView();
		if (wv == null || !wv.isInstance())
		{
			return false;
		}

		final var mapRegions = wv.getMapRegions();
		return mapRegions != null && Arrays.stream(mapRegions).anyMatch(regions::contains);
	}

	private boolean insideDoomOfMokhaiotl()
	{
		return insideInstanceRegion(DOOM_REGION_IDS);
	}

	private boolean insideGauntlet()
	{
		return client.getVarbitValue(VarbitID.PLAYER_IN_GAUNTLET) > 0;
	}

	private boolean insideNightmare()
	{
		return insideRegion(NIGHTMARE_REGION_IDS);
	}

	private boolean vanillaLowDetailPluginEnabled()
	{
		final String pluginEnabled = configManager.getConfiguration(RuneLiteConfig.GROUP_NAME, "lowmemoryplugin");
		if (!Boolean.parseBoolean(pluginEnabled))
		{
			return false;
		}
		return configManager.getConfig(LowMemoryConfig.class).lowDetail();
	}

	private boolean vanillaLowDetailPluginHideLowerPlanesEnabled()
	{
		final String pluginEnabled = configManager.getConfiguration(RuneLiteConfig.GROUP_NAME, "lowmemoryplugin");
		if (!Boolean.parseBoolean(pluginEnabled))
		{
			return false;
		}
		return configManager.getConfig(LowMemoryConfig.class).hideLowerPlanes();
	}

	// ====================================================================================

	enum AutomaticLowDetailRegion
	{
		CUSTOM_REGION_ID,
		CHAMBERS_OF_XERIC,
		THEATRE_OF_BLOOD,
		TOMBS_OF_AMASCUT,
		INFERNO,
		HALLOWED_SEPULCHRE,
		DOOM_OF_MOKHAIOTL,
		GAUNTLET,
		NIGHTMARE
	}
}

package com.lowdetailraids;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(AutomaticLowDetailConfig.GROUP)
public interface AutomaticLowDetailConfig extends Config
{
	String GROUP = "lowdetailraids";

	@ConfigItem(keyName = "regionIdsLowDetail", name = "Low Detail Region IDs", description = "Comma-separated region IDs where Low Detail will be enabled", position = 0)
	default String regionIdsLowDetail()
	{
		return "";
	}
	@ConfigItem(keyName = "regionIdsHideLowerPlanes", name = "Hide Lower Planes Region IDs", description = "Comma-separated region IDs where lower planes will be hidden", position = 1)
	default String regionIdsHideLowerPlanes()
	{
		return "";
	}

	@ConfigSection(
			name = "Chambers of Xeric",
			description = "",
			position = 2
	)
	String chambersOfXeric = "chambersOfXericSection";
	@ConfigItem(keyName = "chambersOfXeric", name = "Low Detail", description = "Whether to enable Low Detail while inside the Chambers of Xeric", position = 0, section = chambersOfXeric)
	default boolean chambersOfXericLowDetail()
	{
		return true;
	}
	@ConfigItem(keyName = "chambersOfXericHideLowerPlanes", name = "Hide Lower Planes", description = "Whether to hide lower planes while inside the Chambers of Xeric", position = 1, section = chambersOfXeric)
	default boolean chambersOfXericHideLowerPlanes()
	{
		return true;
	}

	@ConfigSection(
			name = "Theatre of Blood",
			description = "",
			position = 3
	)
	String theatreOfBlood = "theatreOfBloodSection";
	@ConfigItem(keyName = "theatreOfBlood", name = "Low Detail", description = "Whether to enable Low Detail while inside the Theatre of Blood", position = 0, section = theatreOfBlood)
	default boolean theatreOfBloodLowDetail()
	{
		return true;
	}
	@ConfigItem(keyName = "theatreOfBloodHideLowerPlanes", name = "Hide Lower Planes", description = "Whether to hide lower planes while inside the Theatre of Blood", position = 1, section = theatreOfBlood)
	default boolean theatreOfBloodHideLowerPlanes()
	{
		return true;
	}

	@ConfigSection(
			name = "Tombs of Amascut",
			description = "",
			position = 4
	)
	String tombsOfAmascut = "tombsOfAmascutSection";
	@ConfigItem(keyName = "tombsOfAmascut", name = "Low Detail", description = "Whether to enable Low Detail while inside the Tombs of Amascut", position = 0, section = tombsOfAmascut)
	default boolean tombsOfAmascutLowDetail()
	{
		return true;
	}
	@ConfigItem(keyName = "tombsOfAmascutHideLowerPlanes", name = "Hide Lower Planes", description = "Whether to hide lower planes while inside the Tombs of Amascut", position = 1, section = tombsOfAmascut)
	default boolean tombsOfAmascutHideLowerPlanes()
	{
		return false;
	}

	@ConfigSection(
			name = "Inferno",
			description = "",
			position = 5
	)
	String inferno = "infernoSection";
	@ConfigItem(keyName = "inferno", name = "Low Detail", description = "Whether to enable Low Detail while inside the Inferno (and TzHaar-Ket-Rak's Challenges)", position = 0, section = inferno)
	default boolean infernoLowDetail()
	{
		return true;
	}
	@ConfigItem(keyName = "infernoHideLowerPlanes", name = "Hide Lower Planes", description = "Whether to hide lower planes while inside the Inferno (and TzHaar-Ket-Rak's Challenges)", position = 1, section = inferno)
	default boolean infernoHideLowerPlanes()
	{
		return false;
	}

	@ConfigSection(
			name = "Hallowed Sepulchre",
			description = "",
			position = 6
	)
	String hallowedSepulchre = "hallowedSepulchreSection";
	@ConfigItem(keyName = "hallowedSepulchre", name = "Low Detail", description = "Whether to enable Low Detail while inside the Hallowed Sepulchre", position = 0, section = hallowedSepulchre)
	default boolean hallowedSepulchreLowDetail()
	{
		return true;
	}
	@ConfigItem(keyName = "hallowedSepulchreHideLowerPlanes", name = "Hide Lower Planes", description = "Whether to hide lower planes while inside the Hallowed Sepulchre", position = 1, section = hallowedSepulchre)
	default boolean hallowedSepulchreHideLowerPlanes()
	{
		return true;
	}

	@ConfigSection(
			name = "Doom of Mokhaiotl",
			description = "",
			position = 7
	)
	String doomOfMokhaiotl = "doomOfMokhaiotlSection";
	@ConfigItem(keyName = "doomOfMokhaiotlLowDetail", name = "Low Detail", description = "Whether to enable Low Detail while inside the Doom of Mokhaiotl", position = 0, section = doomOfMokhaiotl)
	default boolean doomOfMokhaiotlLowDetail()
	{
		return true;
	}
	@ConfigItem(keyName = "doomOfMokhaiotlHideLowerPlanes", name = "Hide Lower Planes", description = "Whether to hide lower planes while inside the Doom of Mokhaiotl", position = 1, section = doomOfMokhaiotl)
	default boolean doomOfMokhaiotlHideLowerPlanes()
	{
		return false;
	}

	@ConfigSection(
			name = "The Gauntlet",
			description = "",
			position = 8
	)
	String gauntlet = "gauntletSection";
	@ConfigItem(keyName = "gauntletLowDetail", name = "Low Detail", description = "Whether to enable Low Detail while inside the Gauntlet and Corrupted Gauntlet", position = 0, section = gauntlet)
	default boolean gauntletLowDetail()
	{
		return true;
	}
	@ConfigItem(keyName = "gauntletHideLowerPlanes", name = "Hide Lower Planes", description = "Whether to hide lower planes while inside the Gauntlet and Corrupted Gauntlet", position = 1, section = gauntlet)
	default boolean gauntletHideLowerPlanes()
	{
		return false;
	}

	@ConfigSection(
			name = "Nightmare",
			description = "",
			position = 9
	)
	String nightmare = "nightmareSection";
	@ConfigItem(keyName = "nightmareLowDetail", name = "Low Detail", description = "Whether to enable Low Detail while inside the Nightmare and Phosani's Nightmare", position = 0, section = nightmare)
	default boolean nightmareLowDetail()
	{
		return true;
	}
	@ConfigItem(keyName = "nightmareHideLowerPlanes", name = "Hide Lower Planes", description = "Whether to hide lower planes while inside the Nightmare and Phosani's Nightmare", position = 1, section = nightmare)
	default boolean nightmareHideLowerPlanes()
	{
		return false;
	}
}
